def runtime_status():
    try:
        import gymnasium as gym
        import vizdoom

        from vizdoom import gymnasium_wrapper  # noqa: F401
        env = gym.make("VizdoomBasic-v1", render_mode="rgb_array", frame_skip=4)
        env.reset(seed=0)
        env.close()
        return f"ViZDoom {vizdoom.__version__} · READY"
    except Exception as exc:
        return f"startup check pending · {type(exc).__name__}"


def _make_env(environment: str, seed: int):
    import gymnasium as gym
    from vizdoom import gymnasium_wrapper  # noqa: F401

    env = gym.make(environment, render_mode="rgb_array", frame_skip=4)
    env = gym.wrappers.TransformObservation(
        env,
        lambda observation: observation["screen"],
        observation_space=env.observation_space["screen"],
    )
    env = gym.wrappers.GrayscaleObservation(env, keep_dim=False)
    env = gym.wrappers.ResizeObservation(env, (84, 84))
    env = gym.wrappers.FrameStackObservation(env, stack_size=4)
    env.reset(seed=seed)
    return env


def _record(model, env, artifacts: Path, seed: int, task):
    observation, _ = env.reset(seed=seed)
    frames: list[np.ndarray] = []
    max_steps = int(task["max_steps"])
    for step in range(max_steps):
        frame = env.render()
        if frame is None and isinstance(observation, np.ndarray) and observation.ndim == 3:
            frame = observation
        if frame is not None and (step % 2 == 0 or step < 20):
            frames.append(np.asarray(frame))
        action, _ = model.predict(observation, deterministic=True)
        observation, _, terminated, truncated, _ = env.step(action)
        if terminated or truncated:
            break
    env.close()
    return save_gif(frames, artifacts / f"{task['key']}-learned-policy.gif", fps=18)


def run(key: str, budget: int, learning_rate: float, gamma: float, epsilon: float, seed: int):
    task = next(item for item in TASKS if item["key"] == key)
    environment = task["environment"]
    yield from train_sb3(
        root=ROOT,
        task=task,
        make_train_env=lambda: _make_env(environment, seed),
        make_eval_env=lambda: _make_env(environment, seed + 1_000),
        make_record_env=lambda: _make_env(environment, seed + 10_000),
        budget=budget,
        learning_rate=learning_rate,
        gamma=gamma,
        epsilon=epsilon,
        seed=seed,
        record_episode=lambda model, env, artifacts, record_seed: _record(model, env, artifacts, record_seed, task),
    )
